script:
frappe.listview_settings["Workflow Task"] = {
    hide_name_column: true,
    hide_name_filter: true,
    get_form_link(doc) {
        return frappe.utils.get_form_link(
            doc.doc,
            doc.wt_docname
          );
    },
    onload: function(listview) {
        listview.page_length = Math.max( listview.total_count, 20);
    },
    before_render: function() {
        let listview = cur_list;
        let docNames = [];
        let targetDocType = null;

        // Проверяем наличие фильтров
        if (listview.filters && listview.filters.length > 0) {
            listview.filters.forEach((filter) => {
                if (filter[0] === 'Workflow Task' && 
                    filter[1] === 'doc' && 
                    filter[2] === '=') {
                    
                    // Определяем целевой DocType
                    if (filter[3] === 'User Timesheet Position') {
                        targetDocType = 'User Timesheet Position';
                    } else if (filter[3] === 'Application For Leave') {
                        targetDocType = 'Application For Leave';
                    }
                }
            });

            // Собираем docnames
            if (targetDocType) {
                listview.data.forEach(item => {
                    if (item.wt_docname) {
                        docNames.push(item.wt_docname);
                    }
                });
            }
        }

        // Перенаправление
        if (docNames.length > 0 && targetDocType) {
            docNames = [...new Set(docNames)];
            console.log('Redirecting to', targetDocType, 'with names:', docNames);

            // Правильный способ перенаправления
            frappe.route_options = {
                name: ['in', docNames],
                user: ['!=', frappe.session.user]
            };
            history.replaceState(null, null, frappe.router.make_url( frappe.get_prev_route() ) );
            frappe.set_route('List', targetDocType);
        }
    }
};
